-- Complete the verified 2026 professional study maps for batch thirteen.
-- The local filename is aligned with the migration version recorded by production Supabase.
-- This migration replaces only the eight target schools' published 2026 offerings.
-- All syllabus points, resources, draft/inactive rows, and non-target offerings are frozen.

create temporary table batch_thirteen_protected_offering_drafts on commit drop as
select to_jsonb(o) as row_data
from public.admission_offerings o
where o.status <> 'published' or o.active = false;

create temporary table batch_thirteen_protected_points on commit drop as
select to_jsonb(p) as row_data
from public.syllabus_points p;

create temporary table batch_thirteen_protected_resources on commit drop as
select to_jsonb(r) as row_data
from public.resources r;

create temporary table batch_thirteen_protected_other_offerings on commit drop as
select to_jsonb(o) as row_data
from public.admission_offerings o
where not (
  o.year = 2026
  and o.status = 'published'
  and o.active = true
  and o.school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')
);

do $$
begin
  if (select count(*) from batch_thirteen_protected_offering_drafts) <> 4
     or (select count(*) from batch_thirteen_protected_points where row_data->>'status' <> 'published' or (row_data->>'active')::boolean = false) <> 33
     or (select count(*) from batch_thirteen_protected_resources where row_data->>'status' <> 'published') <> 0 then
    raise exception 'Batch thirteen stopped: protected draft/inactive baseline changed';
  end if;

  if (select version from public.content_versions where id = 'public-content') <> 111
     or (select count(*) from public.admission_offerings where status = 'published' and active = true) <> 174
     or (select count(*) from public.syllabus_points where status = 'published' and active = true) <> 1033
     or (select count(*) from public.resources where status = 'published') <> 80 then
    raise exception 'Batch thirteen stopped: production baseline changed';
  end if;

  if (select count(*) from public.admission_offerings
      where year = 2026 and status = 'published' and active = true
        and school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')) <> 12 then
    raise exception 'Batch thirteen stopped: target offering baseline changed';
  end if;
end $$;
delete from public.admission_offerings
where year = 2026
  and status = 'published'
  and active = true
  and school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue');

