  array(select jsonb_array_elements_text(source.public)),
  array(select jsonb_array_elements_text(source.professional)),
  source.plan, source_urls.charter_url, source_urls.syllabus_url,
  '2026招生章程与专业课考试大纲已核验', date '2026-10-18', true, 'published', source.sort
from source
join source_urls using (school);

do $$
declare
  target record;
  actual_rows integer;
  actual_programs integer;
  actual_plans integer;
begin
  for target in
    select * from (values
    ('bbc',5,5,200),
    ('hfuu',2,2,100),
    ('fynu',4,4,230),
    ('ahnu',15,15,1900),
    ('aufe',14,7,850),
    ('hblg',31,22,2400),
    ('wjut',30,20,1000),
    ('hfue',15,15,2400)
    ) as expected(school_slug, offering_rows, program_count, plan_total)
  loop
    select count(*), count(distinct program_name), sum(plan_count)
      into actual_rows, actual_programs, actual_plans
    from (
      select o.plan_count, unnest(o.program_names) as program_name
      from public.admission_offerings o
      where o.year = 2026 and o.status = 'published' and o.active = true
        and o.school_slug = target.school_slug
    ) expanded;

    if actual_rows <> target.offering_rows
       or actual_programs <> target.program_count
       or actual_plans <> target.plan_total then
      raise exception 'Batch thirteen stopped: % totals are %, %, %, expected %, %, %',
        target.school_slug, actual_rows, actual_programs, actual_plans,
        target.offering_rows, target.program_count, target.plan_total;
    end if;
  end loop;

  if exists (
    (select row_data from batch_thirteen_protected_offering_drafts
     except
     select to_jsonb(o) from public.admission_offerings o where o.status <> 'published' or o.active = false)
    union all
    (select to_jsonb(o) from public.admission_offerings o where o.status <> 'published' or o.active = false
     except
     select row_data from batch_thirteen_protected_offering_drafts)
  ) then
    raise exception 'Batch thirteen stopped: protected draft/inactive offerings changed';
  end if;

  if exists (
    (select row_data from batch_thirteen_protected_points
     except select to_jsonb(p) from public.syllabus_points p)
    union all
    (select to_jsonb(p) from public.syllabus_points p
     except select row_data from batch_thirteen_protected_points)
  ) then
    raise exception 'Batch thirteen stopped: syllabus points changed';
  end if;

  if exists (
    (select row_data from batch_thirteen_protected_resources
     except select to_jsonb(r) from public.resources r)
    union all
    (select to_jsonb(r) from public.resources r
     except select row_data from batch_thirteen_protected_resources)
  ) then
    raise exception 'Batch thirteen stopped: resources changed';
  end if;

  if exists (
    (select row_data from batch_thirteen_protected_other_offerings
     except
     select to_jsonb(o) from public.admission_offerings o
     where not (
       o.year = 2026 and o.status = 'published' and o.active = true
       and o.school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')
     ))
    union all
    (select to_jsonb(o) from public.admission_offerings o
     where not (
       o.year = 2026 and o.status = 'published' and o.active = true
       and o.school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')
     )
     except select row_data from batch_thirteen_protected_other_offerings)
  ) then
    raise exception 'Batch thirteen stopped: non-target offerings changed';
  end if;

  if (select count(*) from public.admission_offerings where status = 'published' and active = true) <> 278
     or (select count(distinct school_slug) from public.admission_offerings where status = 'published' and active = true) <> 41
     or (select count(*) from public.admission_offerings
         where year = 2026 and status = 'published' and active = true
           and school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')) <> 116
     or (select sum(plan_count) from public.admission_offerings
         where year = 2026 and status = 'published' and active = true
           and school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')) <> 9080 then
    raise exception 'Batch thirteen stopped: published offering totals are incorrect';
  end if;

  if exists (
    select 1
    from public.admission_offerings o
    where o.year = 2026 and o.status = 'published' and o.active = true
      and o.school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')
      and (
        cardinality(o.program_names) <> 1
        or o.exam_scheme_id is null
        or o.plan_count is null
        or o.training_site is null
        or o.eligible_major_categories is null
        or cardinality(o.public_subjects) <> 2
        or cardinality(o.professional_subjects) <> 2
        or o.charter_url is null
        or o.syllabus_url is null
      )
  ) then
    raise exception 'Batch thirteen stopped: an offering is incomplete or combines programs';
  end if;

  if exists (
    select 1
    from public.admission_offerings o
    where o.year = 2026 and o.status = 'published' and o.active = true
      and o.school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')
    group by o.school_slug, o.exam_scheme_id
    having count(distinct jsonb_build_array(o.public_subjects, o.professional_subjects)::text) <> 1
  ) then
    raise exception 'Batch thirteen stopped: different exam subjects share one scheme';
  end if;

  if exists (
    select 1
    from public.admission_offerings o
    where o.year = 2026 and o.status = 'published' and o.active = true
      and o.school_slug in ('bbc','hfuu','fynu','ahnu','aufe','hblg','wjut','hfue')
    group by o.school_slug, o.public_subjects, o.professional_subjects
    having count(distinct o.exam_scheme_id) <> 1
  ) then
    raise exception 'Batch thirteen stopped: identical exam schemes were duplicated';
  end if;

  if (select count(*) from public.syllabus_points where status = 'published' and active = true) <> 1033
     or (select count(*) from public.resources where status = 'published') <> 80
     or (select count(*) from public.syllabus_points where status = 'draft' and active = false) <> 33
     or (select count(*) from public.admission_offerings where year = 2027 and status = 'draft' and active = false) <> 4 then
    raise exception 'Batch thirteen stopped: frozen content counts changed';
  end if;

  if (select version from public.content_versions where id = 'public-content') <= 111 then
    raise exception 'Batch thirteen stopped: public content version was not advanced';
  end if;
end $$;
